runtime_path_workaround.source:
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
/* Lean 4.35 requests its own executable via /proc/<pid>/exe. This runtime's
   supported self alias is /proc/self/exe. Only normalize that exact self path;
   all other filesystem calls are delegated unchanged. */
ssize_t readlink(const char *path, char *buf, size_t bufsiz) {
  static ssize_t (*next_readlink)(const char *, char *, size_t);
  if (!next_readlink) next_readlink = dlsym(RTLD_NEXT, "readlink");
  char self_path[80];
  snprintf(self_path, sizeof self_path, "/proc/%ld/exe", (long)getpid());
  if (strcmp(path, self_path) == 0) path = "/proc/self/exe";
  return next_readlink(path, buf, bufsiz);
}
